import java.util.*;

public class Main {
    boolean isUgly(int n) {
        if (n <= 0) {
            return false;                  // ugly numbers are always positive
        }
        int[] factors = {2, 3, 5};
        for (int factor : factors) {
            while (n % factor == 0) {
                n /= factor;                  // keep dividing out this factor as long as it divides evenly
            }
        }
        return n == 1;                      // only 1s and the allowed factors should remain
    }

    public static void main(String[] args) {
        int n = 6;
        Main solution = new Main();
        System.out.println(solution.isUgly(n));
    }
}

